export interface Club { id: string; name: string; short: string; country: string; primary: string; secondary: string }
export const CLUBS: Club[] = CLUB_ROWS.map(([id, name, short, country, primary, secondary]) => ({ id, name, short, country, primary, secondary }))
  .sort((a, b) => a.name.localeCompare(b.name, 'en'));
export const CLUB_BY_ID: Record<string, Club> = Object.fromEntries(CLUBS.map((c) => [c.id, c]));

/** Nicknames people actually type. */
const ALIASES: Record<string, string[]> = {
  tottenham: ['spurs'], 'man-united': ['man utd', 'man u', 'united'], 'man-city': ['city', 'man c'], wolves: ['wolves'],
  'nottm-forest': ['forest', 'nottingham'], 'sheff-wednesday': ['wednesday', 'owls'], 'sheff-united': ['blades'], 'west-brom': ['baggies'],
  'west-ham': ['hammers', 'irons'], arsenal: ['gunners'], newcastle: ['toon', 'magpies'], inter: ['internazionale'], 'red-star': ['crvena zvezda'],
  psg: ['paris'], bayern: ['bayern munchen'], qpr: ['rangers qpr'], 'brighton': ['seagulls'], 'crystal-palace': ['palace', 'eagles'],
};

/** Search by name, short name, a few letters of each word ("man u") or a nickname ("spurs"). */
export function searchClubs(query: string, limit = 30): Club[] {
  const q = query.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  if (!q) return CLUBS.slice(0, limit);
  const norm = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const words = q.split(/\s+/);
  return CLUBS
    .map((c) => {
      const n = norm(c.name);
      const alias = (ALIASES[c.id] ?? []).some((a) => a.startsWith(q));
      const score = n.startsWith(q) || alias ? 0 : c.short.toLowerCase() === q ? 1 : words.every((w) => n.split(/[\s&-]+/).some((p) => p.startsWith(w))) ? 2 : n.includes(q) ? 3 : 9;
      return { c, score };
    })
    .filter((x) => x.score < 9)
    .sort((a, b) => a.score - b.score || a.c.name.localeCompare(b.c.name))
    .slice(0, limit)
    .map((x) => x.c);
}
